INSERT INTO public.exam_sections (id, exam_id, title, order_index) VALUES ('exam-calculus-2-2023-sec-0', 'exam-calculus-2-2023', '一、单选题', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, title = EXCLUDED.title, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2023-s0-0', 'exam-calculus-2-2023', 'exam-calculus-2-2023-sec-0', 0, '设平面通过点(1,1,1)和点', '设平面 $\\Pi$ 通过点(1,1,1)和点(0,1,-1)且垂直于平面 $x + y + z = 0$ ，则平面 $\\Pi$ 的方程为（）.', '["$2x - y - z = 0$","$2x + y - z = 0$","$2x + y + z = 0$","$3x - 2y - z = 0$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2023长沙理工大学高数A（二）期末', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2023-s0-1', 'exam-calculus-2-2023', 'exam-calculus-2-2023-sec-0', 0, '设D是第二象限的一个有界闭域，', '设 D 是第二象限的一个有界闭域，且 0 < y < 1，令 $T_{1} = \\iint_{D} yx^{3} d\\sigma, \\quad T_{2} = \\iint_{D} y^{2} x^{3} d\\sigma,$ $T_{3} = \\iint_{D} \\sqrt{y} x^{3} d\\sigma$ ，则（）.', '["$T_{1} \\\\leq T_{2} \\\\leq T_{3}$","$T_{2} \\\\leq T_{1} \\\\leq T_{3}$","$T_{3} \\\\leq T_{2} \\\\leq T_{1}$","$T_{3} \\\\leq T_{1} \\\\leq T_{2}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2023长沙理工大学高数A（二）期末', 1) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2023-s0-2', 'exam-calculus-2-2023', 'exam-calculus-2-2023-sec-0', 0, '下列说法正确的是（）.', '下列说法正确的是（）.', '["函数 $f(x, y)$ 在点 $(x, y)$ 处偏导数存在，则 $f(x, y)$ 在点 $(x, y)$ 处连续.","函数 $f(x, y)$ 在点 $(x, y)$ 处连续，则 $f(x, y)$ 在点 $(x, y)$ 处偏导数存在.","函数 $f(x, y)$ 在点 $(x, y)$ 处可微，则 $f(x, y)$ 在点 $(x, y)$ 处两个偏导数都连续.","函数 $f(x, y)$ 在点 $(x, y)$ 处两个偏导数都连续，则 $f(x, y)$ 在点 $(x, y)$ 处可微."]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2023长沙理工大学高数A（二）期末', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2023-s0-3', 'exam-calculus-2-2023', 'exam-calculus-2-2023-sec-0', 0, '设，则.', '设 $D=\\{(x,y)|a^{2}\\leq x^{2}+y^{2}\\leq b^{2}\\}$ ，则 $\\iint_{D}\\sqrt{x^{2}+y^{2}}d\\sigma=(\\quad)$ .', '["$-\\\\frac{\\\\pi}{3}(b^{3}-a^{3})$","$\\\\frac{\\\\pi}{3}(b^{3}-a^{3})$","$-\\\\frac{2\\\\pi}{3}(b^{3}-a^{3})$","$\\\\frac{2\\\\pi}{3}(b^{3}-a^{3})$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2023长沙理工大学高数A（二）期末', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-calculus-2-2023-s0-4', 'exam-calculus-2-2023', 'exam-calculus-2-2023-sec-0', 0, '下列级数条件收敛的是（）', '下列级数条件收敛的是（）。', '["$\\\\sum_{n=1}^{\\\\infty} (-1)^n \\\\frac{1}{\\\\ln (1+n)}$","$\\\\sum_{n=1}^{\\\\infty} (-1)^n \\\\frac{1}{n^2}$","$\\\\sum_{n=1}^{\\\\infty} (-1)^n n^2$","$\\\\sum_{n=1}^{\\\\infty} (-1)^n \\\\frac{\\\\pi^{n-2}}{3^n}$"]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '2023长沙理工大学高数A（二）期末', 4) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
